    initial_build_paths: Object.freeze(["packages/db/migrations/0215_legacy_account_links.sql", "packages/db/src/postgres-legacy-link-store.ts", "packages/db/test/postgres-legacy-link.test.ts", "apps/gateway/src/legacy-login.ts", "apps/gateway/test/legacy-login.test.ts", "apps/gateway/src/legacy-link-http.ts", "apps/gateway/test/legacy-link-http.test.ts", "apps/gateway/test/legacy-link-mutations.mjs", "apps/gateway/src/web-ui.ts", "apps/gateway/src/routes/index.ts", "apps/gateway/src/routes/context.ts", "apps/gateway/src/wiring/context.ts", "apps/gateway/src/contributions/index.ts", "apps/gateway/src/wiring/access.ts", "apps/gateway/src/contributions/access.ts", "packages/db/src/access/index.ts", "apps/gateway/src/wiring/profile.ts", "apps/gateway/src/contributions/profile.ts", "packages/db/src/profile/index.ts"]),
