    initial_build_paths: Object.freeze(["packages/db/migrations/0217_person_area.sql", "packages/reference-catalogue/src/types.ts", "packages/db/src/postgres-person-location-store.ts", "packages/db/test/postgres-person-location.test.ts", "packages/profile/src/area.ts", "packages/profile/src/index.ts", "packages/profile/src/types.ts", "packages/profile/src/profile.ts", "packages/profile/test/area.test.ts", "packages/profile/test/area-mutations.mjs", "apps/gateway/src/area-http.ts", "apps/gateway/test/area-http.test.ts", "apps/gateway/src/web-ui.ts", "apps/gateway/src/routes/index.ts", "apps/gateway/src/routes/context.ts", "apps/gateway/src/wiring/context.ts", "apps/gateway/src/contributions/index.ts", "apps/gateway/src/wiring/profile.ts", "apps/gateway/src/contributions/profile.ts", "packages/db/src/profile/index.ts"]),
