    initial_build_paths: Object.freeze(["apps/gateway/src/documents-actions-http.ts", "apps/gateway/test/documents-actions-http.test.ts", "apps/gateway/test/documents-actions-mutations.mjs", "apps/gateway/src/profile-avatar.ts", "apps/gateway/test/profile-avatar.test.ts", "apps/gateway/src/documents-page.ts", "apps/gateway/test/documents-page.test.ts", "apps/gateway/src/web-ui.ts", "apps/gateway/test/web-ui.test.ts", "apps/gateway/src/ui/profile-copy.ts", "apps/gateway/src/routes/index.ts", "apps/gateway/src/routes/context.ts", "apps/gateway/src/wiring/context.ts", "apps/gateway/src/contributions/index.ts", "apps/gateway/src/wiring/profile.ts", "apps/gateway/src/contributions/profile.ts", "packages/db/src/profile/index.ts"]),
