    initial_build_paths: Object.freeze(["packages/db/migrations/0219_civil_id_reviews.sql", "packages/db/src/postgres-civil-id-review-store.ts", "packages/db/test/postgres-civil-id-review.test.ts", "packages/private-documents/src/staff-delivery.ts", "packages/private-documents/test/staff-delivery.test.mjs", "packages/private-documents/test/staff-delivery-mutations.mjs", "apps/gateway/src/civil-id-review-http.ts", "apps/gateway/test/civil-id-review-http.test.ts", "apps/gateway/test/civil-id-review-mutations.mjs", "apps/gateway/src/web-ui.ts", "apps/gateway/src/routes/index.ts", "apps/gateway/src/routes/context.ts", "apps/gateway/src/wiring/context.ts", "apps/gateway/src/contributions/index.ts", "apps/gateway/src/wiring/profile.ts", "apps/gateway/src/contributions/profile.ts", "packages/db/src/profile/index.ts"]),
